#pragma once

#include <algorithm>
#include <array>
#include <cstdint>

namespace breakwater {

/// The missions the game offers: seeds 0 to kOfferedSeeds - 1, minus those the
/// solver could not prove winnable (concept criterion 4).
inline constexpr std::uint64_t kOfferedSeeds = 1000;

/// The node budget the proof sweep uses; part of what "proven" means.
inline constexpr std::uint64_t kProofBudget = 1'000'000;

/// Seeds in [0, kOfferedSeeds) the solver could not prove within kProofBudget.
/// Generated by `bw_solve --range 0-999 --budget 1000000` and held to it by
/// `bw_solve --check-offered`, which fails on any disagreement either way.
inline constexpr std::array<std::uint64_t, 19> kRejectedSeeds{0,   172, 183, 263, 336, 434, 499, 559, 578, 628,
                                                              674, 745, 751, 787, 794, 803, 809, 850, 965};

[[nodiscard]] constexpr bool is_offered(std::uint64_t seed) noexcept {
    return seed < kOfferedSeeds && std::ranges::find(kRejectedSeeds, seed) == kRejectedSeeds.end();
}

/// The first offered seed after `seed`, wrapping within the offered range.
[[nodiscard]] constexpr std::uint64_t next_offered(std::uint64_t seed) noexcept {
    for (std::uint64_t i = 1; i <= kOfferedSeeds; ++i) {
        const std::uint64_t candidate = (seed + i) % kOfferedSeeds;
        if (is_offered(candidate)) {
            return candidate;
        }
    }
    return 0; // Unreachable while fewer seeds are rejected than offered.
}

static_assert(std::ranges::is_sorted(kRejectedSeeds));
static_assert(!is_offered(kOfferedSeeds));
static_assert(std::ranges::all_of(kRejectedSeeds, [](std::uint64_t s) { return s < kOfferedSeeds && !is_offered(s); }));
static_assert(is_offered(next_offered(kRejectedSeeds.front())));
static_assert(next_offered(kOfferedSeeds - 1) < kOfferedSeeds);

} // namespace breakwater
